  complete: () => void;
}

class Observable<T> {
  private producer: (observer: Observer<T>) => void;

  constructor(producer: (observer: Observer<T>) => void) {
    this.producer = producer;
  }

  subscribe(observer: Observer<T>): void {
    this.producer(observer);
  }

  filter(predicate: (value: T) => boolean): Observable<T> {
    // TODO 1 : retourne un Observable qui ne transmet que les valeurs pour lesquelles predicate est vrai
    //          (et propage complete)
    return new Observable<T>(() => {});
  }

  map<R>(project: (value: T) => R): Observable<R> {
    // TODO 2 : retourne un Observable qui transmet project(valeur) (et propage complete)
    return new Observable<R>(() => {});
  }
}

function of<T>(...values: T[]): Observable<T> {
  return new Observable<T>((observer) => {
    for (const value of values) {
      observer.next(value);
    }
    observer.complete();
  });
}

function logCalls<A extends unknown[], R>(name: string, fn: (...args: A) => R): (...args: A) => R {
  // TODO 3 : retourne une fonction qui appelle fn puis affiche `appel <nom>(<arguments séparés par ", ">) -> <résultat>`
  return fn;
}

of(1, 2, 3, 4)
  .filter((value) => value % 2 === 0)
  .map((value) => value * value)
  .subscribe({
    next: (value) => console.log(`valeur: ${value}`),
    complete: () => console.log('terminé'),
  });

const add = logCalls('add', (a: number, b: number) => a + b);
add(1, 2);

